import React, { useEffect, useMemo, useState } from "react";
import "../styles/battle.css";

/*
 * Battle Spirits simplified battle component.
 *
 * This implementation extends the previous version with the following features:
 * - Both players start at 3 life.
 * - Life, reserve, trash counts and control buttons are consolidated in a single HUD
 *   for each player.
 * - Each turn consists of three steps: core step (gain one core), draw step (draw one
 *   card), and refresh step (move cores from trash back to reserve). Summoning and
 *   attacking are disabled until both the core and draw steps have been completed.
 * - Spirits that attack become exhausted for the remainder of the turn and are
 *   automatically refreshed at the start of the next turn.
 * - A simple block system: when a spirit attacks, the defending player is asked
 *   whether to block. If blocking, they select one of their spirits to block with.
 *   The BP (battle power) of the attacker and blocker are compared; the spirit with
 *   lower BP is sent to the trash. If the attacker is not blocked, the defender
 *   loses life equal to the attacker’s symbol count.
 * - The level and BP of each summoned spirit are displayed for both sides.
 * - The opponent’s hand is represented by a series of facedown card-back images.
 */

// TODO: update the import path to point at your card back image. The uploaded
// image used in the specification should be placed in your project’s public
// assets folder (e.g. public/images/card-back.jpeg) and imported here.
import CardBackImage from "./images/card-back.jpeg";

// Dummy data for cards; in your real project this should be imported from
// ../data/cards as before.
// Each card should include levels with BP information. If your data does not
// contain BP, adjust the getBP helper below accordingly.
const cards = [];

export default function Battle() {
  // Create a 20-card deck from the available cards (repeat if fewer).
  const fullDeck = useMemo(() => {
    const deck = [];
    for (let i = 0; i < 20; i++) {
      const c = cards[i % cards.length];
      deck.push({ ...c, deckIndex: i });
    }
    return deck;
  }, []);

  /**
   * Player state. Both players start with 3 life and 4 reserve cores. Trash
   * starts at 0. Each zone holds either null or an object
   * { card, cores, attacked }.
   */
  const [me, setMe] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null] });
  const [op, setOp] = useState({ life: 3, reserve: 4, trash: 0, zones: [null, null, null, null] });
  const [deck, setDeck] = useState([]);
  const [hand, setHand] = useState([]);
  const [opDeck, setOpDeck] = useState([]);
  const [opHand, setOpHand] = useState([]);
  const [selected, setSelected] = useState(null);
  /**
   * `turn` indicates which side is active: 0 = me, 1 = opponent.
   * `step` cycles through 0 (core), 1 (draw), 2 (refresh). Summon and
   * attack actions are only allowed at step 2 or later. After step 2
   * completes, further calls to nextStep wrap around and effectively do
   * nothing until the turn ends.
   */
  const [turn, setTurn] = useState(0);
  const [step, setStep] = useState(0);

  /**
   * Initialize both players’ decks and hands. Each draws four cards from
   * their deck at the start of the game. This effect only runs once.
   */
  useEffect(() => {
    // Player deck & hand
    const d = [...fullDeck];
    const drawn = [];
    for (let i = 0; i < 4 && d.length > 0; i++) {
      const idx = Math.floor(Math.random() * d.length);
      drawn.push(d.splice(idx, 1)[0]);
    }
    setDeck(d);
    setHand(drawn);

    // Opponent deck & hand
    const od = [...fullDeck];
    const odrawn = [];
    for (let i = 0; i < 4 && od.length > 0; i++) {
      const idx = Math.floor(Math.random() * od.length);
      odrawn.push(od.splice(idx, 1)[0]);
    }
    setOpDeck(od);
    setOpHand(odrawn);
  }, [fullDeck]);

  /**
   * Advance to the next step. On step 0 the active player gains 1 reserve.
   * On step 1 the active player draws 1 card from their deck. On step 2
   * the active player moves all cores from trash back into reserve. After
   * step 2, additional calls to nextStep do nothing until the turn ends.
   */
  const nextStep = () => {
    // Only the active player can perform step actions
    if (turn !== 0) return;
    const phase = step % 3;
    if (phase === 0) {
      setMe(m => ({ ...m, reserve: m.reserve + 1 }));
    } else if (phase === 1) {
      if (deck.length > 0) {
        const idx = Math.floor(Math.random() * deck.length);
        const picked = deck[idx];
        const nd = [...deck];
        nd.splice(idx, 1);
        setDeck(nd);
        setHand(h => [...h, picked]);
      }
    } else if (phase === 2) {
      setMe(m => ({ ...m, reserve: m.reserve + m.trash, trash: 0 }));
    }
    setStep(s => s + 1);
  };

  /**
   * End the current turn. Swaps the active player and resets the step
   * counter. All exhausted spirits on the new active side are refreshed.
   */
  const endTurn = () => {
    setTurn(t => {
      const next = t === 0 ? 1 : 0;
      // Refresh spirits for the next active player
      if (next === 0) {
        setMe(m => ({ ...m, zones: m.zones.map(z => (z ? { ...z, attacked: false } : null)) }));
      } else {
        setOp(o => ({ ...o, zones: o.zones.map(z => (z ? { ...z, attacked: false } : null)) }));
      }
      return next;
    });
    setStep(0);
  };

  /**
   * Helper: determine the current level of a card based on cores. The
   * previous utils/bspo.js file provided this helper; re-implemented here
   * for brevity. Returns the level object containing { lv, core, bp? }.
   */
  const levelFromCores = (card, cores) => {
    if (!card || !card.levels) return { lv: 1, core: 0 };
    let result = card.levels[0];
    for (const lv of card.levels) {
      if (cores >= lv.core) result = lv;
    }
    return result;
  };

  /**
   * Helper: compute the BP (Battle Power) for a spirit at a given core count.
   * If your card data has a `bp` property on each level, this function
   * returns that value. Otherwise, adjust to reflect your data structure.
   */
  const getBP = (card, cores) => {
    const lv = levelFromCores(card, cores);
    return lv.bp || lv.power || card.bp || 0;
  };

  /**
   * Summon a card from hand into one of your zones. Only allowed when
   * turn===0 and step>=2 (i.e. after core and draw steps). Reductions
   * and core cost computation can be adjusted via your utils.
   */
  const summonTo = (idx) => {
    if (turn !== 0) return;
    if (step % 3 < 2) {
      alert("ドローステップとコアステップを終えてから召喚できます。");
      return;
    }
    if (selected === null) return;
    if (me.zones[idx] !== null) return;

    const card = hand[selected];
    // Apply reductions based on existing spirits (simple example: -1 per same-colour spirit)
    // Replace with your own reduction logic from utils/bspo.js.
    const sameColorCount = me.zones.filter(z => z && z.card && z.card.color === card.color).length;
    const costReduction = Math.min(sameColorCount, 3);
    const baseCost = card.cost || 0;
    const actualCost = Math.max(0, baseCost - costReduction);
    const needCores = card.levels?.[0]?.core || 0;
    const totalPay = actualCost + needCores;
    if (me.reserve < totalPay) {
      alert(`コア不足：必要${totalPay} / 手持ち${me.reserve}`);
      return;
    }

    const zones = [...me.zones];
    zones[idx] = { card, cores: needCores, attacked: false };

    setMe(m => ({
      ...m,
      reserve: m.reserve - totalPay,
      trash: m.trash + actualCost,
      zones,
    }));
    const newHand = [...hand];
    newHand.splice(selected, 1);
    setHand(newHand);
    setSelected(null);
  };

  /**
   * Level up a spirit by paying additional cores. Only allowed after core
   * and draw steps. Levels and core costs are derived from the card’s
   * level array.
   */
  const levelUp = (idx) => {
    if (turn !== 0) return;
    if (step % 3 < 2) {
      alert("ドローステップとコアステップを終えてからレベルアップできます。");
      return;
    }
    const z = me.zones[idx];
    if (!z) return;
    const lvNow = levelFromCores(z.card, z.cores);
    const lvArr = z.card.levels;
    const pos = lvArr.findIndex(l => l.lv === lvNow.lv);
    const nextLv = lvArr[pos + 1];
    if (!nextLv) return;
    const needMore = nextLv.core - z.cores;
    if (needMore > me.reserve) {
      alert("コア不足");
      return;
    }
    const zones = [...me.zones];
    zones[idx] = { ...z, cores: nextLv.core };
    setMe(m => ({ ...m, reserve: m.reserve - needMore, zones }));
  };

  /**
   * Level down a spirit, refunding excess cores back to reserve. Only
   * allowed after core and draw steps. Typically used if you need
   * additional cores for other actions.
   */
  const levelDown = (idx) => {
    if (turn !== 0) return;
    if (step % 3 < 2) {
      alert("ドローステップとコアステップを終えてからレベルダウンできます。");
      return;
    }
    const z = me.zones[idx];
    if (!z) return;
    const lvNow = levelFromCores(z.card, z.cores);
    const lvArr = z.card.levels;
    const pos = lvArr.findIndex(l => l.lv === lvNow.lv);
    const prevLv = lvArr[pos - 1];
    if (!prevLv) return;
    const refund = z.cores - prevLv.core;
    const zones = [...me.zones];
    zones[idx] = { ...z, cores: prevLv.core };
    setMe(m => ({ ...m, reserve: m.reserve + refund, zones }));
  };

  /**
   * Execute an attack with one of your spirits. Prompts the defending
   * player to block with one of their own spirits if available. The
   * attacking spirit and blocking spirit’s BP are compared and the
   * losing spirit is sent to the trash. If the attack is unblocked,
   * the defender loses life equal to the attacker’s symbol count.
   */
  const attack = (idx) => {
    if (turn !== 0) return;
    if (step % 3 < 2) {
      alert("ドローステップとコアステップを終えてから攻撃できます。");
      return;
    }
    const z = me.zones[idx];
    if (!z || z.attacked) return;
    const attackerBP = getBP(z.card, z.cores);
    const symbols = z.card.symbolCount || 1;
    // If opponent has at least one spirit, ask whether they block
    let didBlock = false;
    let blockIdx = -1;
    if (op.zones.some(s => s)) {
      if (window.confirm("ブロックしますか？（OK=ブロック、キャンセル=しない）")) {
        // Build list of candidate indexes (1-based for user)
        const candidates = op.zones.map((s, i) => (s ? i + 1 : null)).filter(v => v !== null);
        const answer = window.prompt(`どのスピリットでブロックしますか？ ${candidates.join(", ")} から選んでください。`);
        if (answer) {
          const chosen = parseInt(answer, 10);
          const chosenIdx = chosen - 1;
          if (chosenIdx >= 0 && chosenIdx < op.zones.length && op.zones[chosenIdx]) {
            didBlock = true;
            blockIdx = chosenIdx;
          }
        }
      }
    }
    if (didBlock) {
      const blocker = op.zones[blockIdx];
      const blockerBP = getBP(blocker.card, blocker.cores);
      // Compare BP; the weaker spirit goes to trash. In case of tie, both are destroyed.
      if (attackerBP > blockerBP) {
        // Destroy blocker
        setOp(o => {
          const zones = [...o.zones];
          zones[blockIdx] = null;
          return { ...o, zones, trash: o.trash + 1 };
        });
      } else if (attackerBP < blockerBP) {
        // Destroy attacker
        setMe(m => {
          const zones = [...m.zones];
          zones[idx] = null;
          return { ...m, zones, trash: m.trash + 1 };
        });
        return;
      } else {
        // Both destroyed on tie
        setOp(o => {
          const zones = [...o.zones];
          zones[blockIdx] = null;
          return { ...o, zones, trash: o.trash + 1 };
        });
        setMe(m => {
          const zones = [...m.zones];
          zones[idx] = null;
          return { ...m, zones, trash: m.trash + 1 };
        });
        return;
      }
      // Attacker survives but marks as attacked
      setMe(m => {
        const zones = [...m.zones];
        zones[idx] = { ...z, attacked: true };
        return { ...m, zones };
      });
    } else {
      // No block: deal life damage
      setOp(o => ({ ...o, life: Math.max(0, o.life - symbols) }));
      // Mark attacker as having attacked
      setMe(m => {
        const zones = [...m.zones];
        zones[idx] = { ...z, attacked: true };
        return { ...m, zones };
      });
    }
  };

  /**
   * Render a player’s hand as a series of images. For the opponent, facedown
   * card-back images are shown instead of actual card art. When showCards
   * is true, display the real card images (used for the player’s own hand).
   */
  const renderHand = (cardsArr, showCards) => {
    if (cardsArr.length === 0) {
      return <span>手札ゾーン</span>;
    }
    return (
      <div className="hand-cards">
        {cardsArr.map((c, i) => (
          showCards ? (
            <img
              key={c.deckIndex}
              src={c.img}
              alt={c.name}
              className={`card-img ${selected === i ? "selected" : ""}`}
              onClick={() => setSelected(prev => (prev === i ? null : i))}
            />
          ) : (
            <img
              key={i}
              src={CardBackImage}
              alt="op-card-back"
              className="card-img back"
            />
          )
        ))}
      </div>
    );
  };

  return (
    <div className="board">
      {/* Unified HUD displaying life, reserve, trash, and controls */}
      <div className="hud" style={{ gridColumn: "1 / -1", justifyContent: "space-between" }}>
        <div style={{ display: "flex", gap: 16 }}>
          <span>
            手番: <b>{turn === 0 ? "あなた" : "相手"}</b>
          </span>
          <span>
            ステップ: <b>{(step % 3) + 1} / 3</b>
          </span>
          <span>
            LIFE <b>{me.life}</b>
          </span>
          <span>
            RESERVE <b>{me.reserve}</b>
          </span>
          <span>
            TRASH <b>{me.trash}</b>
          </span>
        </div>
        <div style={{ display: "flex", gap: 10 }}>
          <button className="next-btn" onClick={nextStep} disabled={turn !== 0}>
            次のステップ
          </button>
          <button className="next-btn" onClick={endTurn}>
            ターン終了
          </button>
        </div>
      </div>
      {/* Player side */}
      <section className="side my-side">
        {/* Display board zones */}
        <div className="field">
          {me.zones.map((z, i) =>
            !z ? (
              <div
                key={i}
                className={`zone ${selected !== null && turn === 0 ? "placeable" : ""}`}
                onClick={() => summonTo(i)}
              >
                <span>ゾーン{i + 1}</span>
              </div>
            ) : (
              <div key={i} className="zone filled">
                <img src={z.card.img} alt={z.card.name} className="zone-card" />
                <div className="zone-badge">Lv{levelFromCores(z.card, z.cores).lv}</div>
                <div className="zone-badge bp">BP{getBP(z.card, z.cores)}</div>
                <div className="zone-controls">
                  <button className="btn-small" onClick={() => levelDown(i)}>
                    -
                  </button>
                    <button className="btn-small" onClick={() => levelUp(i)}>
                      +
                  </button>
                  <button className="btn-small warn" disabled={z.attacked} onClick={() => attack(i)}>
                    ATK
                  </button>
                </div>
              </div>
            )
          )}
        </div>
        {/* Hand */}
        <footer className="hand hand-bottom">{renderHand(hand, true)}</footer>
      </section>
      <div className="divider" />
      {/* Opponent side */}
      <section className="side op-side">
        <header className="hand hand-top">
          {/* Show facedown cards representing opponent’s hand */}
          {renderHand(opHand, false)}
        </header>
        <div className="field">
          {op.zones.map((z, i) =>
            !z ? (
              <div key={i} className="zone">
                <span>{i + 1}ゾーン</span>
              </div>
            ) : (
              <div key={i} className="zone filled">
                <img className="zone-card" src={z.card.img} alt={z.card.name} />
                <div className="zone-badge">Lv{levelFromCores(z.card, z.cores).lv}</div>
                <div className="zone-badge bp">BP{getBP(z.card, z.cores)}</div>
              </div>
            )
          )}
        </div>
        {/* Opponent HUD */}
        <footer className="hud">
          <span className="hud-item red">
            LIFE <b>{op.life}</b>
          </span>
          <span className="hud-item red">
            RESERVE <b>{op.reserve}</b>
          </span>
          <span className="hud-item red">
            TRASH <b>{op.trash}</b>
          </span>
        </footer>
      </section>
    </div>
  );
}
